from datetime import datetime, timedelta
from typing import Dict, List, Optional, Any


class Scheduler:
    def __init__(self) -> None:
        self.appointments: Dict[int, Dict[str, Any]] = {}  # appointment_id -> {patient, doctor, start, end, cancelled, cancellation_time}
        self.next_id = 1
        self.patient_appointments: Dict[str, List[int]] = {}  # patient -> list of appointment_ids

    def book(self, patient: str, doctor: str, start: datetime, end: datetime,
             now: datetime) -> int:
        # Requirement 3: Booking an appointment that starts before `now` raises ValueError
        if start < now:
            raise ValueError("Appointment cannot start before current time")

        # Requirement 2: Booking an appointment that overlaps another appointment of the same doctor
        # Only consider non-cancelled appointments and cancelled appointments that were cancelled <24h before start
        for appointment in self.appointments.values():
            if self._is_active_for_scheduling(appointment, now):
                if appointment['doctor'] == doctor:
                    # Check for overlap: two intervals [a,b] and [c,d] overlap if a < d and c < b
                    if start < appointment['end'] and appointment['start'] < end:
                        raise ValueError("Appointment overlaps with existing appointment for this doctor")

        # Requirement 5: A patient can have at most one upcoming appointment
        if patient in self.patient_appointments:
            for appointment_id in self.patient_appointments[patient]:
                appointment = self.appointments[appointment_id]
                if self._is_upcoming(appointment, now):
                    raise ValueError("Patient already has an upcoming appointment")

        # Create new appointment
        appointment_id = self.next_id
        self.next_id += 1

        self.appointments[appointment_id] = {
            'patient': patient,
            'doctor': doctor,
            'start': start,
            'end': end,
            'cancelled': False,
            'cancellation_time': None
        }

        # Track patient's appointments
        if patient not in self.patient_appointments:
            self.patient_appointments[patient] = []
        self.patient_appointments[patient].append(appointment_id)

        return appointment_id

    def cancel(self, appointment_id: int, now: datetime) -> None:
        if appointment_id not in self.appointments:
            return

        appointment = self.appointments[appointment_id]

        # If appointment is already cancelled, do nothing
        if appointment.get('cancelled', False):
            return

        # Mark as cancelled and record cancellation time
        appointment['cancelled'] = True
        appointment['cancellation_time'] = now

    def is_free(self, doctor: str, start: datetime, end: datetime) -> bool:
        """True if the doctor can be booked between start and end."""
        for appointment in self.appointments.values():
            # Skip appointments that are cancelled AND were cancelled at least 24h before their start time
            if self._is_active_for_scheduling(appointment, start):
                if appointment['doctor'] == doctor:
                    # Check for overlap
                    if start < appointment['end'] and appointment['start'] < end:
                        return False
        return True

    def _is_active_for_scheduling(self, appointment: Dict[str, Any], now: datetime) -> bool:
        """
        Returns True if the appointment blocks the schedule (i.e., is active for scheduling purposes).
        An appointment blocks scheduling if:
        - It's not cancelled, OR
        - It's cancelled but the cancellation happened less than 24 hours before the appointment's start time
        """
        if not appointment.get('cancelled', False):
            return True

        cancellation_time = appointment.get('cancellation_time')
        if cancellation_time is None:
            return True  # Shouldn't happen, but be safe

        # Appointment blocks scheduling if cancelled <24h before its start time
        # i.e., if cancellation_time > (appointment['start'] - 24h)
        return cancellation_time > appointment['start'] - timedelta(hours=24)

    def _is_upcoming(self, appointment: Dict[str, Any], now: datetime) -> bool:
        """Returns True if appointment is not cancelled and ends after now"""
        return not appointment.get('cancelled', False) and appointment['end'] > now
